  (mkTbNocRouter_instance->INST_router.INST_outQ_4.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_canRoute_0.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_canRoute_1.set_clk_0)("CLK");
  (mkTbNocRouter_instance->INST_router.INST_canRoute_2.set_clk_0)("CLK");
